import com.sun.net.httpserver.*;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;

/** Local educational application. Not designed for internet exposure. */
public class StudentApp {
    static final Map<String,String> students = new TreeMap<>();
    static final Map<String,String> courses = new TreeMap<>();
    static final Set<String> enrollments = new TreeSet<>();
    static final Map<String,String> attendance = new TreeMap<>();
    static final Map<String,Integer> marks = new TreeMap<>();
    static final Map<String,String> sessions = new ConcurrentHashMap<>();
    static final Object LOCK = new Object();
    static final Path STORE = Paths.get(System.getenv().getOrDefault("STUDENT_DATA", "data/store.properties"));
    static final String ADMIN_USER = System.getenv().getOrDefault("STUDENT_ADMIN_USER", "admin");
    static final String ADMIN_PASS = System.getenv().getOrDefault("STUDENT_ADMIN_PASS", "Demo123!");
    static final String CSS = "body{font:16px Arial;margin:0;background:#f4f6f8;color:#182432}header{background:#17324f;color:white;padding:22px 5%}nav{background:white;padding:16px 5%;border-bottom:1px solid #ddd}nav a{margin-right:16px}main{max-width:1000px;margin:28px auto;padding:24px;background:white;border:1px solid #ddd}input,button{font:inherit;padding:8px;margin:5px}button{background:#17324f;color:white;border:0}table{width:100%;border-collapse:collapse}td,th{border:1px solid #ccc;padding:9px;text-align:left}.ok{background:#e4f5e8;padding:8px}.error{background:#fae6e6;padding:8px}";

    static boolean validId(String s) { return s != null && s.matches("[A-Za-z0-9-]{3,20}"); }
    static boolean validName(String s) { return s != null && !s.strip().isEmpty() && s.strip().length() <= 100 && s.chars().noneMatch(Character::isISOControl); }
    static int percent(int attended, int total) { if(total<=0 || attended<0 || attended>total) throw new IllegalArgumentException("Invalid attendance"); return (int)Math.round(100.0*attended/total); }
    static boolean validMark(int m) { return m>=0 && m<=100; }
    static String result(Integer m) { return m == null ? "Pending" : m < 40 ? "Fail" : "Pass"; }
    static String key(String student,String course) { return student+"|"+course; }
    static String esc(Object value) { String s=String.valueOf(value); return s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;").replace("'","&#39;"); }
    static String decode(String s) { return URLDecoder.decode(s,StandardCharsets.UTF_8); }
    static Map<String,String> params(String raw) { Map<String,String> m=new HashMap<>(); if(raw==null||raw.isEmpty())return m; for(String x:raw.split("&")){String[] p=x.split("=",2);m.put(decode(p[0]),p.length>1?decode(p[1]):"");}return m; }
    static String field(String name,String title) { return "<label>"+title+" <input name='"+name+"' required></label>"; }
    static String form(String action,String fields,String button,String csrf) { return "<form action='"+action+"' method='post'><input type='hidden' name='csrf' value='"+esc(csrf)+"'>"+fields+"<button>"+button+"</button></form>"; }
    static String table(String[] heads,Collection<String[]> data){StringBuilder b=new StringBuilder("<table><tr>");for(String h:heads)b.append("<th>").append(esc(h)).append("</th>");b.append("</tr>");for(String[] row:data){b.append("<tr>");for(String v:row)b.append("<td>").append(esc(v)).append("</td>");b.append("</tr>");}return b.append("</table>").toString();}
    static List<String[]> rows(Map<String,? extends Object> records){List<String[]> r=new ArrayList<>();records.forEach((k,v)->r.add(new String[]{k,String.valueOf(v)}));return r;}
    static String page(String title,String body){return "<!doctype html><html><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>"+esc(title)+"</title><style>"+CSS+"</style></head><body><header><h1>Student Management System</h1><small>ISWE305P Software Testing</small></header><nav><a href='/'>Dashboard</a><a href='/login'>Login</a><a href='/register'>Registration</a><a href='/students'>Students</a><a href='/courses'>Courses</a><a href='/enrollment'>Enrollment</a><a href='/attendance'>Attendance</a><a href='/marks'>Marks</a><a href='/reports'>Reports</a><a href='/logout'>Logout</a></nav><main><h2>"+esc(title)+"</h2>"+body+"</main></body></html>";}
    static void response(HttpExchange e,int status,String title,String text){try {byte[] raw=page(title,text).getBytes(StandardCharsets.UTF_8);e.getResponseHeaders().set("Content-Type","text/html; charset=utf-8");e.sendResponseHeaders(status,raw.length);try(OutputStream out=e.getResponseBody()){out.write(raw);}}catch(IOException ex){throw new UncheckedIOException(ex);}}
    static void save() throws IOException {Properties p=new Properties(); students.forEach((k,v)->p.setProperty("student."+k,v));courses.forEach((k,v)->p.setProperty("course."+k,v));for(String k:enrollments)p.setProperty("enrollment."+k,"yes");attendance.forEach((k,v)->p.setProperty("attendance."+k,v));marks.forEach((k,v)->p.setProperty("marks."+k,String.valueOf(v)));Path parent=STORE.toAbsolutePath().getParent();Files.createDirectories(parent);Path tmp=Files.createTempFile(parent,"sms-",".tmp");try(OutputStream out=Files.newOutputStream(tmp)){p.store(out,"Student Management System");}try{Files.move(tmp,STORE,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}catch(AtomicMoveNotSupportedException ex){Files.move(tmp,STORE,StandardCopyOption.REPLACE_EXISTING);}}
    static void load() throws IOException {if(!Files.exists(STORE))return;Properties p=new Properties();try(InputStream in=Files.newInputStream(STORE)){p.load(in);}students.clear();courses.clear();enrollments.clear();attendance.clear();marks.clear();for(String k:p.stringPropertyNames()){String v=p.getProperty(k);if(k.startsWith("student."))students.put(k.substring(8),v);else if(k.startsWith("course."))courses.put(k.substring(7),v);else if(k.startsWith("enrollment."))enrollments.add(k.substring(11));else if(k.startsWith("attendance."))attendance.put(k.substring(11),v);else if(k.startsWith("marks."))marks.put(k.substring(6),Integer.parseInt(v));}}
    static String cookie(HttpExchange e){List<String> c=e.getRequestHeaders().get("Cookie");if(c==null)return "";for(String header:c)for(String part:header.split(";")){String x=part.strip();if(x.startsWith("SID="))return x.substring(4);}return "";}
    static String csrf(HttpExchange e){return sessions.get(cookie(e));}
    static void handle(HttpExchange e){synchronized(LOCK){String path=e.getRequestURI().getPath();String method=e.getRequestMethod();String title=path.equals("/")?"Dashboard":path.substring(1);int status=200;String body="";
        try{
            if(!method.equals("GET")&&!method.equals("POST")){response(e,405,"Method not allowed","Unsupported method");return;}
            if(path.equals("/health")){response(e,200,"Health","OK");return;}
            String request="";if(method.equals("POST")){byte[] bytes=e.getRequestBody().readNBytes(8193);if(bytes.length>8192){response(e,413,"Payload too large","Request limit exceeded");return;}request=new String(bytes,StandardCharsets.UTF_8);}
            Map<String,String> p=params(request);
            if(path.equals("/login")){
                if(method.equals("POST")){if(ADMIN_USER.equals(p.get("username"))&&ADMIN_PASS.equals(p.get("password"))){String sid=UUID.randomUUID().toString(),token=UUID.randomUUID().toString();sessions.put(sid,token);e.getResponseHeaders().add("Set-Cookie","SID="+sid+"; HttpOnly; SameSite=Strict; Path=/");body="<p class='ok'>Authentication accepted. <a href='/'>Open dashboard</a></p>";}else{status=401;body="<p class='error'>Invalid credentials</p>";}}
                else body="<form method='post'>"+field("username","Username")+"<label>Password <input type='password' name='password' required></label><button>Login</button></form>";
                response(e,status,"Login",body);return;
            }
            String token=csrf(e);
            if(token==null){response(e,401,"Unauthorized","Sign in at <a href='/login'>Login</a>.");return;}
            if(method.equals("POST")&&!token.equals(p.get("csrf"))){response(e,403,"Forbidden","Invalid CSRF token");return;}
            if(path.equals("/logout")){if(method.equals("POST")){sessions.remove(cookie(e));e.getResponseHeaders().add("Set-Cookie","SID=; Max-Age=0; Path=/");body="Logged out";}else body=form("/logout","","Confirm logout",token);}
            else if(path.equals("/")){body="<p>Manage student records, courses, enrollment, attendance, marks, and reports.</p><p>Students: "+students.size()+" | Courses: "+courses.size()+" | Enrollments: "+enrollments.size()+"</p>";}
            else if(path.equals("/register")){if(method.equals("POST")){String id=p.getOrDefault("id","").strip(),name=p.getOrDefault("name","").strip();if(!validId(id)||!validName(name)){status=400;body="Invalid student identifier or name";}else if(students.containsKey(id)){status=409;body="Duplicate student";}else{students.put(id,name);save();body="<p class='ok'>Student registered</p>";}}body+=form("/register",field("id","Register number")+field("name","Student name"),"Add student",token);}
            else if(path.equals("/students")){if(method.equals("POST")){String id=p.getOrDefault("id",""),op=p.getOrDefault("op","");if(!students.containsKey(id)){status=404;body="Student not found";}else if(op.equals("delete")){if(enrollments.stream().anyMatch(x->x.startsWith(id+"|"))){status=409;body="Remove enrollment first";}else{students.remove(id);save();body="Student removed";}}else if(op.equals("update")&&validName(p.get("name"))){students.put(id,p.get("name").strip());save();body="Student updated";}else{status=400;body="Invalid operation";}}body+=table(new String[]{"Student ID","Name"},rows(students));body+="<h3>Update student</h3>"+form("/students",field("id","ID")+field("name","New name")+"<input type='hidden' name='op' value='update'>","Update",token)+"<h3>Delete student</h3>"+form("/students",field("id","ID")+"<input type='hidden' name='op' value='delete'>","Delete",token);}
            else if(path.equals("/courses")){if(method.equals("POST")){String code=p.getOrDefault("code","").strip(),name=p.getOrDefault("name","").strip(),op=p.getOrDefault("op","create");if(op.equals("delete")){if(!courses.containsKey(code)){status=404;body="Course not found";}else if(enrollments.stream().anyMatch(x->x.endsWith("|"+code))){status=409;body="Remove enrollment first";}else{courses.remove(code);save();body="Course deleted";}}else if(!validId(code)||!validName(name)){status=400;body="Invalid course";}else if(op.equals("update")&&courses.containsKey(code)){courses.put(code,name);save();body="Course updated";}else if(op.equals("create")&&!courses.containsKey(code)){courses.put(code,name);save();body="Course created";}else{status=409;body="Duplicate or missing course";}}body+=table(new String[]{"Course Code","Title"},rows(courses));body+="<h3>Add course</h3>"+form("/courses",field("code","Code")+field("name","Title"),"Add",token)+"<h3>Edit course</h3>"+form("/courses",field("code","Code")+field("name","Title")+"<input type='hidden' name='op' value='update'>","Update",token)+"<h3>Delete course</h3>"+form("/courses",field("code","Code")+"<input type='hidden' name='op' value='delete'>","Delete",token);}
            else if(path.equals("/enrollment")){if(method.equals("POST")){String id=p.getOrDefault("id",""),code=p.getOrDefault("code",""),k=key(id,code);if(!students.containsKey(id)||!courses.containsKey(code)){status=404;body="Unknown student or course";}else if("delete".equals(p.get("op"))){enrollments.remove(k);attendance.remove(k);marks.remove(k);save();body="Enrollment removed";}else if(!enrollments.add(k)){status=409;body="Duplicate enrollment";}else{save();body="Enrollment saved";}}List<String[]> r=new ArrayList<>();for(String k:enrollments)r.add(new String[]{k});body+=table(new String[]{"Student | Course"},r)+form("/enrollment",field("id","Student ID")+field("code","Course code"),"Enroll",token)+form("/enrollment",field("id","Student ID")+field("code","Course code")+"<input type='hidden' name='op' value='delete'>","Remove enrollment",token);}
            else if(path.equals("/attendance")){if(method.equals("POST")){String k=key(p.getOrDefault("id",""),p.getOrDefault("code",""));if(!enrollments.contains(k)){status=409;body="Enrollment required";}else{try{int a=Integer.parseInt(p.get("attended")),t=Integer.parseInt(p.get("conducted"));int pc=percent(a,t);attendance.put(k,a+"/"+t+" ("+pc+"%)");save();body="Attendance saved: "+pc+"%";}catch(IllegalArgumentException ex){status=400;body="Invalid attendance range or numbers";}}}body+=table(new String[]{"Student | Course","Attendance"},rows(attendance))+form("/attendance",field("id","Student ID")+field("code","Course")+field("attended","Attended")+field("conducted","Conducted"),"Save attendance",token);}
            else if(path.equals("/marks")){if(method.equals("POST")){String k=key(p.getOrDefault("id",""),p.getOrDefault("code",""));if(!enrollments.contains(k)){status=409;body="Enrollment required";}else{try{int mark=Integer.parseInt(p.get("mark"));if(!validMark(mark))throw new IllegalArgumentException();marks.put(k,mark);save();body="Marks saved";}catch(RuntimeException ex){status=400;body="Invalid mark";}}}body+=table(new String[]{"Student | Course","Mark"},rows(marks))+form("/marks",field("id","Student ID")+field("code","Course")+field("mark","Mark / 100"),"Save marks",token);}
            else if(path.equals("/reports")){List<String[]> r=new ArrayList<>();for(String k:enrollments){String[] a=k.split("\\|",2);Integer m=marks.get(k);r.add(new String[]{a[0],students.get(a[0]),a[1],attendance.getOrDefault(k,"Not recorded"),m==null?"Not recorded":String.valueOf(m),result(m)});}body=table(new String[]{"Student ID","Name","Course","Attendance","Marks","Result"},r);}
            else{status=404;body="Page not found";}
        } catch(IllegalArgumentException ex){status=400;body="Invalid input";}catch(Exception ex){status=500;body="Unable to complete operation";}
        response(e,status,title,body);
    }}
    public static void main(String[] args)throws Exception {load();int port=args.length>0?Integer.parseInt(args[0]):8188;HttpServer server=HttpServer.create(new InetSocketAddress("127.0.0.1",port),0);server.createContext("/",StudentApp::handle);server.setExecutor(Executors.newFixedThreadPool(8));server.start();System.out.println("Running at http://127.0.0.1:"+port);}
}
